CREATE TABLE users (id CHAR(36) PRIMARY KEY,email VARCHAR(254) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL);
CREATE TABLE interviews (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,profile JSON NOT NULL,status ENUM('active','complete','abandoned') NOT NULL,integrity_score TINYINT UNSIGNED DEFAULT 100,overall_score TINYINT UNSIGNED NULL,created_at DATETIME NOT NULL,completed_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE questions (id CHAR(36) PRIMARY KEY,interview_id CHAR(36) NOT NULL,position SMALLINT NOT NULL,prompt TEXT NOT NULL,category VARCHAR(40) NOT NULL,rubric TEXT NOT NULL,FOREIGN KEY(interview_id) REFERENCES interviews(id));
CREATE TABLE answers (id CHAR(36) PRIMARY KEY,question_id CHAR(36) NOT NULL,transcript MEDIUMTEXT NOT NULL,voice_metrics JSON NOT NULL,evaluation JSON NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE integrity_events (id CHAR(36) PRIMARY KEY,interview_id CHAR(36) NOT NULL,event_type VARCHAR(64) NOT NULL,severity TINYINT UNSIGNED NOT NULL,metadata JSON NOT NULL,occurred_at DATETIME NOT NULL,FOREIGN KEY(interview_id) REFERENCES interviews(id));
